/**
 * Handles {@link DuplicateOwnerException} thrown when attempting to create an owner that is
 * identical to an existing one. Returns a 409 Conflict status.
 *
 * @param e The {@link DuplicateOwnerException} to be handled
 * @param request {@link HttpServletRequest} object referring to the current request.
 * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
 */
@ExceptionHandler(DuplicateOwnerException.class)
@ResponseBody
public ResponseEntity<ProblemDetail> handleDuplicateOwnerException(DuplicateOwnerException e, HttpServletRequest request) {
    logger.warn("Duplicate owner at {} {}: {}",
        request.getMethod(),
        request.getRequestURI(),
        e.getMessage());
    HttpStatus status = HttpStatus.CONFLICT;
    ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
    return ResponseEntity.status(status).body(detail);
}

/**
 * Handles {@link DailyOwnerRegistrationLimitExceededException} thrown when attempting to create
 * an owner once the maximum number of owners allowed to be registered today has been reached.
 * Returns a 400 Bad Request status.
 *
 * @param e The {@link DailyOwnerRegistrationLimitExceededException} to be handled
 * @param request {@link HttpServletRequest} object referring to the current request.
 * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status
 */
@ExceptionHandler(DailyOwnerRegistrationLimitExceededException.class)
@ResponseBody
public ResponseEntity<ProblemDetail> handleDailyOwnerRegistrationLimitExceededException(DailyOwnerRegistrationLimitExceededException e, HttpServletRequest request) {
    logger.warn("Daily owner registration limit reached at {} {}: {}",
        request.getMethod(),
        request.getRequestURI(),
        e.getMessage());
    HttpStatus status = HttpStatus.BAD_REQUEST;
    ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
    return ResponseEntity.status(status).body(detail);
}

