23	/**
24	 * Experimenter-owned, black-box acceptance base for PetClinic-Evolve.
25	 *
26	 * <p>Every checkpoint is a business rule on the ONE endpoint {@code POST /api/owners};
27	 * tests create owners and read fields back via {@code GET /api/owners/{id}}, so the
28	 * Spring and OfficeFloor arms are judged by identical externals.
29	 *
30	 * <p>Isolation: {@code @Transactional} rolls each test back, so count/quota rules
31	 * (membership number, per-day cap, per-city cap, "most common city") see only the
32	 * seed data plus what the test itself creates — deterministic without polluting
33	 * other tests. {@code @WithMockUser} authenticates as a fixed admin so the audit
34	 * rules can assert a known user name.
35	 *
36	 * <p>Cumulative-safety convention: {@link #ownerNode()} returns a FULLY UNIQUE
37	 * owner, which every rule accepts (no duplicate, no quota) at every checkpoint;
38	 * tests then override only the fields needed to trigger a specific rule. Reject
39	 * cases use data that stays rejected under all later (broader) rules.
40	 */
41	@SpringBootTest
42	@AutoConfigureMockMvc
43	@Transactional
44	@WithMockUser(username = "acceptance-admin", roles = {"OWNER_ADMIN", "VET_ADMIN", "ADMIN"})
45	public abstract class AcceptanceBase {
46	
47		private static final AtomicInteger SEQ = new AtomicInteger(0);
48	
49		@Autowired
50		protected MockMvc mvc;
51	
52		@Autowired
53		protected ObjectMapper om;
54	
55		protected int seq() {
56			return SEQ.incrementAndGet();
57		}
58	
59		// --- unique generators (avoid colliding with seed data or other tests) ---
60	
61		/** Encode n as a lowercase letter string (1->a, 26->z, 27->aa), so generated
62		 *  names satisfy the base app's letters-only owner-name pattern. */
63		protected String letters(int n) {
64			StringBuilder sb = new StringBuilder();
65			for (int x = Math.max(n, 1); x > 0; x /= 26) {
66				x--;
67				sb.insert(0, (char) ('a' + x % 26));
68			}
69			return sb.toString();
70		}
71	
72		/** Unique, letters-only surname (starts with "Sur"). */
73		protected String uniqueLastName() {
74			return "Sur" + letters(seq());
75		}
76	
77		protected String uniqueAddress() {
78			return seq() + " Test Street";
79		}
80	
81		protected String uniqueCity() {
82			return "Town" + seq();
83		}
84	
85		/** A unique 10-digit telephone starting with 2 (seed uses 6xxxxxxxxx). */
86		protected String uniqueTelephone() {
87			return String.format("2%09d", seq());
88		}
89	
90		protected String uniqueEmail() {
91			return "owner" + seq() + "@example.test";
92		}
93	
